import{z as B,x as A,o as E,c as p,q as s,j as l,D as e,d as r,s as i,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"反向代理","description":"","frontmatter":{"title":"反向代理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reverse-proxy.md","filePath":"cs/reverse-proxy.md","lastUpdated":1791413859000}'),d={name:"cs/reverse-proxy.md"};function h(c,a,T,F,m,S){const t=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=s('<h1 id="反向代理" tabindex="-1">反向代理 <a class="header-anchor" href="#反向代理" aria-label="Permalink to &quot;反向代理&quot;">​</a></h1><div class="epigraph"><p>客户端只看见代理；代理终止 TLS、补头、缓存、再开到后端的连接。它是 L7 的具体形态，不是又一种路由协议。</p><footer>—— 据 RFC 9110 网关/代理；HTTP 实践整理</footer></div><p><a href="/cs/l4-l7-load-balancing">L7 LB</a> 常以反向代理实现。<a href="/cs/cdn-cache-hierarchy">CDN</a> 边缘也是。<a href="/cs/maglev-lb">上一课</a> 可把流量先送到代理层。缺口是<strong>代理职责</strong>：Hop-by-hop 头、连接复用、缓冲。本课不把服务发现写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器不直连应用进程。反向代理：证书、HTTP/1.1 到后端 H2 的转换、压缩、WAF、限流令牌桶。<code>X-Forwarded-For</code> 传原 IP，信任边界要钉。<span class="marginnote">常见误区：以为后端见到 X-Forwarded-For 就能无条件相信。客户端可以伪造这个头——只有「最外层代理负责写入、后端只信任与自己直连的那一跳」这条链才是安全的。</span>缓冲：代理若把 SSE 攒满再发，实时死——接 SSE 课。WS 要 Upgrade 透传。</p><p>不要把反向代理写成正向代理（客户端配置出去）。<span class="marginnote">方向记法：正向代理替「客户端」出门办事，服务器不知道真客户是谁；反向代理替「服务器」接客，客户端不知道后面有几台真服务器。两者共用同一套 HTTP 语义，方向相反。</span></p><p><span class="marginnote">RFC 9110 定义 proxy/gateway。本课不点名 nginx 配置项当标准。</span></p><h3 id="面向客户的网关" tabindex="-1">面向客户的网关 <a class="header-anchor" href="#面向客户的网关" aria-label="Permalink to &quot;面向客户的网关&quot;">​</a></h3><p>终止 TLS、改头、池化后端。hop-by-hop 头不盲目转发。缓冲会杀 SSE。与正向代理方向相反。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：客户 → 代理（TLS 终）→ 后端池。对照 Maglev 纯 L4：不终结 TLS。与 SSH 反向隧道不同方向。</p>',11)),(E(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20RP%5B%22%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%22%5D%0A%20%20RP%20--%3E%20TLS%5B%22%E7%BB%88%E6%AD%A2%20TLS%22%5D%0A%20%20RP%20--%3E%20POOL%5B%22%E5%90%8E%E7%AB%AF%E8%BF%9E%E6%8E%A5%E6%B1%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"连接池摊销后端握手，像 HTTP 持久。TSO 在代理两侧。健康检查由代理做。Cookie 会话可钉后端。QUIC 在代理终止，后端常 HTTP/1.1。PMTUD 在两段各自发生。",-1)),(E(),l(n,null,{default:e(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%EF%BC%88TLS%20%E5%B7%B2%E7%BB%88%E6%AD%A2%EF%BC%89%22%5D%20--%3E%20HDR%5B%22%E6%94%B9%E5%86%99%E5%A4%B4%EF%BC%9A%E8%A1%A5%20X-Forwarded-For%22%5D%0A%20%20HDR%20--%3E%20HOP%5B%22%E5%89%A5%E6%8E%89%20hop-by-hop%20%E5%A4%B4%22%5D%0A%20%20HOP%20--%3E%20BUF%5B%22%E7%BC%93%E5%86%B2%E5%86%B3%E7%AD%96%EF%BC%9A%E6%99%AE%E9%80%9A%E8%AF%B7%E6%B1%82%E5%8F%AF%E7%BC%93%E5%86%B2%EF%BC%8CSSE%20%E5%BF%85%E9%A1%BB%E7%9B%B4%E9%80%9A%22%5D%0A%20%20BUF%20--%3E%20POOL%5B%22%E4%BB%8E%E5%90%8E%E7%AB%AF%E8%BF%9E%E6%8E%A5%E6%B1%A0%E5%8F%96%E4%B8%80%E6%9D%A1%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20POOL%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E5%88%B0%E5%90%8E%E7%AB%AF%E5%B9%B6%E7%AD%89%E5%BE%85%E5%93%8D%E5%BA%94%22%5D%0A%20%20FWD%20--%3E%20HEALTH%5B%22%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%E5%A4%B1%E8%B4%A5%E5%88%99%E6%91%98%E9%99%A4%E8%AF%A5%E5%90%8E%E7%AB%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">hop-by-hop 头就是「只属于这一跳」的头，如 Connection、Transfer-Encoding：代理收到就该自己消化，不原样转给下一跳；Authorization 这类端到端头才要透传。转错方向，协议状态机会对不上。</span></p><p>安全：代理是集中点，配置错误会泄露内网。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入缓存键的全部边角。服务发现是下一课。后课默认：反向代理终结客户协议并转发；hop-by-hop 头不盲目转发。</p><p>把代理超时设太短会拆合法 SSE/WS。</p><p>下一课<a href="/cs/service-discovery">服务发现</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反向代理是面向客户的 L7 网关。</li><li>管 TLS、头、池、缓冲。</li><li>与纯 L4 Maglev 分层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9110；HTTP 网关实践。</li></ul>',8))])}const f=B(d,[["render",h]]);export{P as __pageData,f as default};
